#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#define SIZE 1024

int main(void)
{
    int pfd[2], pid;
    ssize_t nread;
    char buf[SIZE];

    if (pipe(pfd) == -1) { perror("pipe failed"); exit(1); }
    if ((pid = fork()) < 0) { perror("fork failed"); exit(2); }

    if (pid == 0) {                         /* child: reader */
        close(pfd[1]);
        while ((nread = read(pfd[0], buf, SIZE)) > 0)
            printf("child read %s\n", buf);
        close(pfd[0]);
    } else {                                /* parent: writer */
        close(pfd[0]);
        strcpy(buf, "hello...");
        write(pfd[1], buf, strlen(buf) + 1); /* include '\0' */
        close(pfd[1]);
    }
    return 0;
}

