static void charatatime(const char *str)
{
    for (const char *p = str; *p; p++) {
        putchar(*p);
        fflush(stdout);
        usleep(1000);
    }
}

int main(void)
{
    int fd[2];
    char token = 'x';
    pipe(fd);
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return 1;
    } else if (pid == 0) {
        read(fd[0], &token, 1);         /* wait for parent */
        charatatime("output from child\n");
    } else {
        charatatime("output from parent\n");
        write(fd[1], &token, 1);        /* child may go */
        wait(NULL);
    }
    return 0;
}

#include <stdio.h>
#include <semaphore.h>
#define N 5                              /* buffer size */

static int buffer[N], in = 0, out = 0;
static sem_t mutex, empty, full;

static void produce(void)
{
    int value;
    if (sem_trywait(&empty) != 0) {     /* no free slot? */
        printf("Buffer is Full\n");
        return;
    }
    printf("Enter the value: ");
    scanf("%d", &value);
    sem_wait(&mutex);                    /* enter critical sect. */
    buffer[in] = value;
    in = (in + 1) % N;
    sem_post(&mutex);                    /* leave critical sect. */
    sem_post(&full);                     /* one more full slot */
}

static void consume(void)
{
    int value;
    if (sem_trywait(&full) != 0) {      /* nothing there? */
        printf("Buffer is Empty\n");
        return;
    }
    sem_wait(&mutex);
    value = buffer[out];
    out = (out + 1) % N;
    sem_post(&mutex);
    sem_post(&empty);                    /* one more empty slot */
    printf("The consumed value is %d\n", value);
}

int main(void)
{
    int choice;
    sem_init(&mutex, 0, 1);              /* binary semaphore  */
    sem_init(&empty, 0, N);              /* N empty slots     */
    sem_init(&full, 0, 0);               /* 0 full slots      */
    for (;;) {
        printf("1. Produce 2. Consume 3. Exit\n");
        printf("Enter your choice: ");
        if (scanf("%d", &choice) != 1 || choice == 3)
            break;
        if (choice == 1) produce();
        else if (choice == 2) consume();
        else printf("Invalid choice\n");
    }
    return 0;
}

#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>

static long long sum;                   /* shared by the threads */

static void *runner(void *param)
{
    int upper = atoi(param);
    sum = 0;
    if (upper > 0)
        for (int i = 1; i <= upper; i++)
            sum += i;
    pthread_exit(0);
}

int main(int argc, char *argv[])
{
    pthread_t tid;                      /* thread identifier  */
    pthread_attr_t attr;                /* thread attributes  */

    if (argc != 2) {
        fprintf(stderr, "usage: %s <integer value>\n", argv[0]);
        return 1;
    }
    if (atoi(argv[1]) < 0) {
        fprintf(stderr, "%d must be >= 0\n", atoi(argv[1]));
        return 1;
    }
    pthread_attr_init(&attr);           /* default attributes */
    pthread_create(&tid, &attr, runner, argv[1]);
    pthread_join(tid, NULL);            /* wait for the thread */
    printf("sum = %lld\n", sum);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int bt[20], wt[20], tat[20], n;
    double wtavg = 0, tatavg = 0;

    printf("Enter the number of processes -- ");
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        printf("Enter Burst Time for Process %d -- ", i);
        scanf("%d", &bt[i]);
    }
    wt[0] = 0;                          /* first process waits 0 */
    tat[0] = bt[0];
    for (int i = 1; i < n; i++) {
        wt[i] = wt[i - 1] + bt[i - 1];  /* wait for all before it */
        tat[i] = wt[i] + bt[i];         /* wait + burst           */
    }
    printf("\nPROCESS\tBURST TIME\tWAITING TIME"
           "\tTURNAROUND TIME\n");
    for (int i = 0; i < n; i++) {
        wtavg += wt[i];
        tatavg += tat[i];
        printf("P%d\t%d\t\t%d\t\t%d\n", i, bt[i], wt[i], tat[i]);
    }
    printf("Average Waiting Time    -- %f\n", wtavg / n);
    printf("Average Turnaround Time -- %f\n", tatavg / n);
    return 0;
}

#include <stdio.h>
#define MAXP 10
#define MAXR 10

int n, m;                               /* processes, resources */
int alloc[MAXP][MAXR], max[MAXP][MAXR], need[MAXP][MAXR];
int avail[MAXR];

/* Safety algorithm: returns 1 and fills seq[] if state is safe */
int is_safe(int seq[])
{
    int work[MAXR], finish[MAXP] = {0}, count = 0;
    for (int j = 0; j < m; j++) work[j] = avail[j];

    while (count < n) {
        int found = 0;
        for (int i = 0; i < n; i++) {
            if (finish[i]) continue;
            int ok = 1;
            for (int j = 0; j < m; j++)
                if (need[i][j] > work[j]) { ok = 0; break; }
            /* P[i] can run to the end */
            if (ok) {
                for (int j = 0; j < m; j++)
                    work[j] += alloc[i][j];
                finish[i] = 1;
                seq[count++] = i;
                found = 1;
            }
        }
        if (!found) return 0;           /* nobody can proceed */
    }
    return 1;
}

int main(void)
{
    int seq[MAXP];
    printf("Enter number of processes and resource types: ");
    scanf("%d %d", &n, &m);
    printf("Enter the Allocation matrix (%d x %d):\n", n, m);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) scanf("%d", &alloc[i][j]);
    printf("Enter the Max matrix (%d x %d):\n", n, m);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++) {
            scanf("%d", &max[i][j]);
            need[i][j] = max[i][j] - alloc[i][j];
        }
    printf("Enter the Available vector (%d values): ", m);
    for (int j = 0; j < m; j++) scanf("%d", &avail[j]);

    printf("\nNeed matrix:\n");
    for (int i = 0; i < n; i++) {
        printf("P%d: ", i);
        for (int j = 0; j < m; j++) printf("%d ", need[i][j]);
        printf("\n");
    }
    if (is_safe(seq)) {
        printf("\nSystem is in a SAFE state.\nSafe sequence: ");
        for (int i = 0; i < n; i++)
            printf("P%d%s", seq[i], i < n - 1 ? " -> " : "\n");
    } else
        printf("\nSystem is NOT safe: deadlock is possible.\n");

    /* Resource-request algorithm */
    int pid, req[MAXR], ok = 1;
    printf("\nTest a request? Enter process id (-1 to skip): ");
    scanf("%d", &pid);
    if (pid >= 0 && pid < n) {
        printf("Enter the request vector: ");
        for (int j = 0; j < m; j++) scanf("%d", &req[j]);
        for (int j = 0; j < m; j++) {
            if (req[j] > need[pid][j]) {
                printf("Error: request exceeds maximum claim.\n");
                return 1;
            }
            if (req[j] > avail[j]) ok = 0;
        }
        if (!ok) {
            printf("P%d must wait: not available.\n", pid);
            return 0;
        }
        for (int j = 0; j < m; j++) {   /* pretend to allocate */
            avail[j] -= req[j];
            alloc[pid][j] += req[j];
            need[pid][j] -= req[j];
        }
        if (is_safe(seq))
            printf("Request can be GRANTED (state stays safe).\n");
        else
            printf("Request DENIED (state would be unsafe).\n");
    }
    return 0;
}

#include <stdio.h>
#define MAXN 20

/* Best-Fit allocation: fixed partitions, one process per block */
int main(void)
{
    int nb, np, bsize[MAXN], psize[MAXN];
    int used[MAXN] = {0}, alloc[MAXN];

    printf("Enter the number of blocks: ");
    scanf("%d", &nb);
    printf("Enter the size of each block: ");
    for (int i = 0; i < nb; i++) scanf("%d", &bsize[i]);
    printf("Enter the number of processes: ");
    scanf("%d", &np);
    printf("Enter the size of each process: ");
    for (int i = 0; i < np; i++) scanf("%d", &psize[i]);

    for (int i = 0; i < np; i++) {
        int pick = -1;
        for (int j = 0; j < nb; j++) {
            if (used[j] || bsize[j] < psize[i]) continue;
            if (pick == -1 || bsize[j] < bsize[pick])
                /* smallest block that fits */
                pick = j;
        }
        alloc[i] = pick;
        if (pick != -1) used[pick] = 1;
    }
    printf("\nProcess\tSize\tBlock\tBlock Size\tFragment\n");
    for (int i = 0; i < np; i++) {
        if (alloc[i] == -1)
            printf("P%d\t%d\tNot allocated\n", i + 1, psize[i]);
        else
            printf("P%d\t%d\t%d\t%d\t\t%d\n", i + 1, psize[i],
                   alloc[i] + 1, bsize[alloc[i]],
                   bsize[alloc[i]] - psize[i]);
    }
    return 0;
}

