int main(void)
{
    int n, f, rs[50], frame[10], last[10], pf = 0;

    printf("Enter the length of reference string -- ");
    scanf("%d", &n);
    printf("Enter the reference string -- ");
    for (int i = 0; i < n; i++) scanf("%d", &rs[i]);
    printf("Enter the number of frames -- ");
    scanf("%d", &f);
    for (int i = 0; i < f; i++) { frame[i] = -1; last[i] = -1; }

    printf("\nPage\tFrames\n");
    for (int i = 0; i < n; i++) {
        int pos = -1;
        for (int j = 0; j < f; j++)
            if (frame[j] == rs[i]) pos = j;
        int fault = (pos == -1);
        if (fault) {
            /* victim: smallest 'last' */
            pos = 0;
            for (int j = 1; j < f; j++)
                if (last[j] < last[pos]) pos = j;
            frame[pos] = rs[i];
            pf++;
        }
        last[pos] = i;                  /* remember time of use */
        printf("%d\t", rs[i]);
        for (int j = 0; j < f; j++) {
            if (frame[j] == -1) printf("- ");
            else printf("%d ", frame[j]);
        }
        if (fault) printf("  <- PF No. %d", pf);
        printf("\n");
    }
    printf("The number of page faults using LRU are %d\n", pf);
    return 0;
}

#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

int main(int argc, char *argv[])
{
    struct flock lock;
    int fd;

    if (argc != 2) {
        fprintf(stderr, "usage: %s <file>\n", argv[0]);
        return 1;
    }
    fd = open(argv[1], O_WRONLY | O_CREAT, 0644);
    if (fd == -1) { perror("open"); return 1; }

    memset(&lock, 0, sizeof(lock));     /* zero the structure   */
    lock.l_type = F_WRLCK;              /* exclusive write lock */
    printf("trying to get lock...\n");
    fflush(stdout);
    fcntl(fd, F_SETLKW, &lock);         /* blocks until granted */
    printf("got lock\n");
    printf("press Enter to release the lock: ");
    fflush(stdout);
    getchar();

    lock.l_type = F_UNLCK;              /* release the lock */
    fcntl(fd, F_SETLKW, &lock);
    printf("unlocked\n");
    close(fd);
    return 0;
}

#include <stdio.h>
