static void sort(int *a, int n)
{
    for (int i = 0; i < n - 1; i++)
        for (int j = 0; j < n - i - 1; j++)
            if (a[j] > a[j + 1]) {
                int t = a[j]; a[j] = a[j + 1]; a[j + 1] = t;
            }
}

int main(void)
{
    int n, head, size, dir, req[20], path[24], p = 0, total = 0;

    printf("Enter the number of requests: ");
    scanf("%d", &n);
    printf("Enter the head position: ");
    scanf("%d", &head);
    printf("Enter the disk size (tracks 0..size-1): ");
    scanf("%d", &size);
    printf("Direction (0 = towards track 0, 1 = towards end): ");
    scanf("%d", &dir);
    printf("Enter the track requests: ");
    for (int i = 0; i < n; i++) scanf("%d", &req[i]);
    sort(req, n);

    if (dir == 0) {                     /* go down, then up */
        for (int i = n - 1; i >= 0; i--)
            if (req[i] < head) path[p++] = req[i];
        path[p++] = 0;                  /* touch the first track */
        for (int i = 0; i < n; i++)
            if (req[i] >= head) path[p++] = req[i];
    } else {                            /* go up, then down */
        for (int i = 0; i < n; i++)
            if (req[i] >= head) path[p++] = req[i];
        path[p++] = size - 1;           /* touch the last track */
        for (int i = n - 1; i >= 0; i--)
            if (req[i] < head) path[p++] = req[i];
    }
    printf("\nFrom\tTo\tMovement\n");
    for (int i = 0; i < p; i++) {
        int d = abs(path[i] - head);
        printf("%d\t%d\t%d\n", head, path[i], d);
        total += d;
        head = path[i];
    }
    printf("\nTotal head movement   : %d\n", total);
    printf("Average head movement : %.2f\n", (float)total / n);
    return 0;
}
